EXPLANATION = {"title": "Chain Integrity", "principle": "Sequential C-alpha atoms stay within 4.5 Angstrom of each other.", "rationale": "The pinned code measures the maximum CA(i)-CA(i+1) distance for sequential same-chain residues; the pinned threshold is 4.5 A (not 4.2 A). WP-8: threshold and description aligned with the pinned code."}
